{
  "requirements": [
    {
      "text": "The system shall ensure compliance with the Apollo Pilot Safety Report and EM Motion Planner specifications at all operational times.",
      "kaos_level": "strategic",
      "rationale": "This ensures adherence to regulatory safety and ethical guidelines for autonomous driving."
    },
    {
      "text": "The system shall implement a multi-layer safety architecture that guarantees active monitoring and response to critical system failures.",
      "kaos_level": "tactical",
      "rationale": "This provides accountability and ensures that safety measures are in place to protect users."
    },
    {
      "text": "The system shall execute a Minimal Risk Maneuver within 5 seconds upon detecting a critical failure, ensuring safe stopping.",
      "kaos_level": "operational",
      "rationale": "This minimizes potential harm to passengers and other road users during emergencies."
    },
    {
      "text": "The system shall continuously monitor and enforce compliance with its defined Operational Design Domain (ODD).",
      "kaos_level": "tactical",
      "rationale": "This ensures the system operates within safe and permissible boundaries, promoting social responsibility."
    },
    {
      "text": "The system shall provide timely HMI warnings to request human takeover whenever ODD compliance is at risk.",
      "kaos_level": "operational",
      "rationale": "This enhances accountability by allowing human oversight in critical situations."
    },
    {
      "text": "The system shall prioritize passenger safety over comfort and speed during emergency maneuvers, relaxing smoothness constraints as necessary.",
      "kaos_level": "tactical",
      "rationale": "This ensures ethical decision-making in conflict scenarios between safety and efficiency."
    },
    {
      "text": "The system shall document all safety and compliance-related decisions and changes for accountability and regulatory purposes.",
      "kaos_level": "strategic",
      "rationale": "This promotes transparency and accountability in the autonomous driving system's operations."
    }
  ]
}
